import Foundation
import Testing
@testable import CoincideCore

/// The fixture is generated by the unchanged, hash-pinned native fork bodies.
/// Swift tests consume those observations; no Node or provider runs here.
@Test func piHistoryForkTransformMatchesOriginalNativeCopyRechainLabelAndMissingFileSemantics() throws {
    let oracle = try piForkOracle()
    #expect(oracle["providerVersion"] == .string("0.80.5"))
    #expect(oracle["scope"]["originalSourceForkWritesTested"] == .bool(true))
    #expect(oracle["scope"]["deterministicClockAndIdentity"] == .bool(true))
    for field in ["fullPackageImported", "installedProviderInvoked", "nativeMutationTested", "originalAlgorithmsRewritten", "runtimeFactoryEvaluated"] {
        #expect(oracle["scope"][field] == .bool(false))
    }
    let modules = try #require(oracle["modules"].array)
    #expect(modules.count == 2)
    #expect(modules.first?["sha256"] == .string("b135a1d19a70cc840658c995539dbcc01fc4eaa3ca6f0ff1df1cbf2c7fbe3cdd"))
    #expect(modules.last?["sha256"] == .string("8229aedb49e0cf12ebb9ed72670e24770c23e4d3ea814fe6f4e91cabe0288745"))
    for category in ["subprocess", "network", "filesystem", "configuration", "identityCreation"] {
        #expect(oracle["guards"][category] == .number(0))
        #expect((piForkCount(oracle["guardSelfTests"][category]) ?? 0) > 0)
    }
    #expect(oracle["allowedOperations"]["opens"] == oracle["allowedOperations"]["closes"])
    for category in ["writes", "identityCreation", "clockObservations"] {
        #expect((piForkCount(oracle["allowedOperations"][category]) ?? 0) > 0)
    }
    let cases = try #require(oracle["cases"].array)
    #expect(cases.count == 13)
    var validated = 0, nativeRejections = 0, policyRefusals = 0, deferredFiles = 0
    for item in cases {
        if item["nativeOperationRejected"] == .bool(true) {
            nativeRejections += 1
            #expect(item["candidate"] == .null)
            continue
        }
        let source = try piForkGraph(item["source"]), candidate = try piForkGraph(item["candidate"])
        let modeRaw = try #require(item["mode"].string)
        let mode = try #require(PiHistoryForkTransform.Mode(rawValue: modeRaw))
        if item["expectedPolicyRefusal"] == .bool(true) {
            #expect(candidate.entries == source.entries && candidate.leafID != source.leafID)
            #expect(throws: PiHistoryGraphError.self) {
                try PiHistoryForkTransform(source: source, mode: mode, retainedLeafID: item["retainedLeafID"].string)
            }
            policyRefusals += 1
            continue
        }
        let transform = try PiHistoryForkTransform(source: source, mode: mode, retainedLeafID: item["retainedLeafID"].string)
        let parent = try #require(item["source"]["sessionFile"].string)
        try transform.validate(candidate: candidate, expectedWorkspacePath: source.header.workspacePath, expectedParentSessionPath: parent)
        #expect(transform.retainedUserEntryIDs == transform.retainedEntries.filter(\.isUser).map(\.id))
        #expect(transform.requiresPersistedFile == (item["candidateFileExists"] == .bool(true)))
        #expect(transform.semanticDigest.count == 64)
        if transform.requiresPersistedFile {
            let persisted = try #require(item["persistedRecords"].array)
            #expect(persisted == [candidate.header.raw] + candidate.entries.map(\.raw))
            let bytes = try piForkJSONL(persisted), fileGraph = try PiHistoryGraph.parse(bytes)
            try transform.validate(candidate: fileGraph, expectedWorkspacePath: source.header.workspacePath, expectedParentSessionPath: parent)
        } else {
            #expect(item["persistedRecords"] == .null)
            deferredFiles += 1
        }
        validated += 1
    }
    #expect(validated == 10 && nativeRejections == 2 && policyRefusals == 1 && deferredFiles == 3)
}

@Test func piHistoryBranchedForkUsesGlobalEffectiveLabelsAndKeepsTheirNativeOrderTimestampsAndRechainedParents() throws {
    let item = try piForkCase("branch-global-label-order-clear-readd-and-parent-rechain")
    let source = try piForkGraph(item["source"]), candidate = try piForkGraph(item["candidate"])
    let transform = try PiHistoryForkTransform(source: source, mode: .branched, retainedLeafID: item["retainedLeafID"].string)
    #expect(transform.retainedEntries.map(\.id) == ["u1", "a1", "u2", "a2"])
    #expect(transform.retainedEntries.map(\.parentID) == [nil, "u1", "a1", "u2"])
    let labels = candidate.entries.filter { $0.kind == .label }
    #expect(labels.map { $0.raw["targetId"].string } == ["u2", "a1", "u1"])
    #expect(labels.map { $0.raw["timestamp"].string } == ["2026-10-23T00:00:00.000Z", "2026-10-23T00:00:02.000Z", "2026-10-23T00:00:03.000Z"])
    #expect(source.entry(id: "l1")?.raw["label"] == .string("First"))
    #expect(labels.last?.raw["label"] == .string("Re-added user"))
    #expect(!candidate.entries.contains { $0.id == "other-u" || $0.id == "l1" || $0.id == "u3" })

    // Label IDs are native outputs, not a copied-ID claim. Re-minting only that
    // suffix and its exact chain remains the same verified semantic transform.
    var rows = candidate.entries.map(\.raw), parent = transform.retainedEntries.last?.id
    for index in transform.retainedEntries.count..<rows.count {
        var object = try #require(rows[index].object)
        let id = "other-generated-label-\(index)"
        object["id"] = .string(id); object["parentId"] = parent.map(JSONValue.string) ?? .null
        rows[index] = .object(object); parent = id
    }
    let renamed = try PiHistoryGraph(header: candidate.header.raw, entries: rows, leafID: parent)
    try transform.validate(candidate: renamed, expectedWorkspacePath: source.header.workspacePath,
                           expectedParentSessionPath: try #require(item["source"]["sessionFile"].string))
}

@Test(arguments: ["payload", "parent", "extra-row", "missing-row", "label-order", "label-text", "label-timestamp", "label-target", "label-extra-field", "header-id", "header-parent", "header-cwd", "header-extra-field", "leaf"])
func piHistoryForkTransformRefusesSubstantiveCandidateChanges(_ mutation: String) throws {
    let item = try piForkCase("branch-global-label-order-clear-readd-and-parent-rechain")
    let source = try piForkGraph(item["source"]), original = try piForkGraph(item["candidate"])
    let transform = try PiHistoryForkTransform(source: source, mode: .branched, retainedLeafID: item["retainedLeafID"].string)
    var header = try #require(original.header.raw.object), rows = original.entries.map(\.raw), leaf = original.leafID
    let labelStart = transform.retainedEntries.count
    func changing(_ index: Int, _ key: String, _ value: JSONValue) throws {
        var object = try #require(rows[index].object); object[key] = value; rows[index] = .object(object)
    }
    switch mutation {
    case "payload":
        var message = try #require(rows[0]["message"].object); message["content"] = .string("altered retained input")
        try changing(0, "message", .object(message))
    case "parent": try changing(1, "parentId", .null)
    case "extra-row":
        let id = "extra-context-metadata"
        rows.append(.object(["type": .string("session_info"), "id": .string(id), "parentId": leaf.map(JSONValue.string) ?? .null,
            "timestamp": .string("2026-10-23T00:00:00.000Z"), "name": .string("unexpected")]))
        leaf = id
    case "missing-row": rows.removeLast(); leaf = rows.last?["id"].string
    case "label-order":
        rows.swapAt(labelStart, labelStart + 1)
        var parent = transform.retainedEntries.last?.id
        for index in labelStart..<rows.count { try changing(index, "parentId", parent.map(JSONValue.string) ?? .null); parent = rows[index]["id"].string }
        leaf = parent
    case "label-text": try changing(labelStart, "label", .string("different label"))
    case "label-timestamp": try changing(labelStart, "timestamp", .string("2026-10-23T00:00:09.000Z"))
    case "label-target": try changing(labelStart, "targetId", .string("a2"))
    case "label-extra-field": try changing(labelStart, "unexpected", .bool(true))
    case "header-id": header["id"] = .string(source.header.sessionID)
    case "header-parent": header["parentSession"] = .string("/other-session.jsonl")
    case "header-cwd": header["cwd"] = .string("/other-workspace")
    case "header-extra-field": header["unexpected"] = .bool(true)
    case "leaf": leaf = rows[0]["id"].string
    default: Issue.record("Unknown synthetic fork mutation.")
    }
    let changed = try PiHistoryGraph(header: .object(header), entries: rows, leafID: leaf)
    let parent = try #require(item["source"]["sessionFile"].string)
    #expect(throws: PiHistoryGraphError.self) {
        try transform.validate(candidate: changed, expectedWorkspacePath: source.header.workspacePath,
                               expectedParentSessionPath: parent)
    }
}

@Test func piHistoryForkTransformPreservesCompactionReferencesAndRefusesFakeFreshContext() throws {
    let item = try piForkCase("branch-compaction-at-retained-native-leaf")
    let source = try piForkGraph(item["source"]), candidate = try piForkGraph(item["candidate"])
    let transform = try PiHistoryForkTransform(source: source, mode: .branched, retainedLeafID: item["retainedLeafID"].string)
    let parent = try #require(item["source"]["sessionFile"].string)
    #expect(candidate.entry(id: "c1")?.raw["firstKeptEntryId"] == source.entry(id: "c1")?.raw["firstKeptEntryId"])
    #expect(candidate.entry(id: "branch-summary")?.raw["fromId"] == source.entry(id: "branch-summary")?.raw["fromId"])
    var rows = candidate.entries.map(\.raw)
    let index = try #require(rows.firstIndex { $0["id"] == .string("c1") })
    var compact = try #require(rows[index].object); compact["firstKeptEntryId"] = .string("u1"); rows[index] = .object(compact)
    let changed = try PiHistoryGraph(header: candidate.header.raw, entries: rows, leafID: candidate.leafID)
    #expect(throws: PiHistoryGraphError.self) { try transform.validate(candidate: changed, expectedWorkspacePath: source.header.workspacePath, expectedParentSessionPath: parent) }
    let fresh = try PiHistoryForkTransform(source: source, mode: .fresh, retainedLeafID: nil)
    #expect(fresh.retainedEntries.isEmpty && fresh.retainedUserEntryIDs.isEmpty && !fresh.requiresPersistedFile)
    #expect(throws: PiHistoryGraphError.self) { try fresh.validate(candidate: candidate, expectedWorkspacePath: source.header.workspacePath, expectedParentSessionPath: parent) }
    #expect(throws: PiHistoryGraphError.self) { try PiHistoryForkTransform(source: source, mode: .fresh, retainedLeafID: "u1") }
    #expect(throws: PiHistoryGraphError.self) { try PiHistoryForkTransform(source: source, mode: .branched, retainedLeafID: nil) }
}

private func piForkOracle() throws -> JSONValue {
    let file = try #require(Bundle.module.url(forResource: "pi_history_fork_original_0_80_5", withExtension: "json", subdirectory: "Fixtures"))
    return try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: file))
}
private func piForkCase(_ name: String) throws -> JSONValue {
    let oracle = try piForkOracle(), cases = try #require(oracle["cases"].array)
    return try #require(cases.first { $0["name"] == .string(name) })
}
private func piForkGraph(_ value: JSONValue) throws -> PiHistoryGraph {
    let entries = try #require(value["entries"].array)
    return try PiHistoryGraph(header: value["header"], entries: entries, leafID: value["runtimeLeafID"].string)
}
private func piForkJSONL(_ rows: [JSONValue]) throws -> Data {
    var bytes = Data()
    for row in rows { bytes.append(try JSONEncoder().encode(row)); bytes.append(10) }
    return bytes
}

private func piForkCount(_ value: JSONValue) -> Double? {
    if case .number(let count) = value { return count }
    return nil
}
